//! W8 golden-fixture harness: Rust DMGS/CP output vs. the reference `fitdistcp`
//! R package.
//!
//! Loads `tests/golden/cp_golden.json` (generated by `tools/generate_cp_golden.R`
//! from the reference R package `stephenjewson/fitdistcp`) and compares the Rust
//! DMGS CP predictive density and quantiles against the reference values.
//!
//! # Tolerance policy
//!
//! The consolidated, canonical tolerance policy lives in
//! [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md); the summary
//! below is the subset relevant to this harness.
//!
//! The Rust port implements the DMGS **expansion**, so the apples-to-apples
//! comparison is against the reference's own DMGS output (`dmgs_pdf` /
//! `dmgs_quantiles`), which the generator emits for the analytic models too.
//!
//! - **DMGS comparison** (`norm`, `expon`, `lnorm`, `gumbel`, `weibull`): as of
//!   **W9** the Rust path uses the same **analytic** derivatives as the
//!   reference (`*_ldda`, `*_lddda`, `*_mu1fa`, `*_mu2fa`, `*_f1fa`, `*_f2fa`),
//!   so the two agree to near machine precision. The observed maximum relative
//!   residuals are: norm `2.8e-14`, expon `4.8e-9`, lnorm `2.6e-8`, gumbel
//!   `1.2e-7`, weibull `1.2e-6` (the weibull is the loosest because its
//!   `powf`-heavy density derivatives carry more round-off). `DMGS_RTOL = 1e-5`
//!   is a 100× tightening of the pre-W9 `1e-3` and still comfortably covers the
//!   weibull round-off while catching any genuine formula/sign bug.
//! - **Analytic-CP cross-check** (`norm`, `expon`, `lnorm`): the reference also
//!   exposes the **exact** analytic CP. The DMGS expansion is a first-order
//!   approximation of that exact integral, so the two differ by the `O(1/n)`
//!   truncation error (observed ~1% at `n = 30`); compared with
//!   `DMGS_TRUNC_RTOL = 5e-2`.
//!
//! # Gamma parameterization (Phase 5, Issue 5)
//!
//! The reference uses R's `dgamma(scale=)` parameterization and a
//! non-homogeneous "type 1" prior `lambdad_cp = c(-1/shape, -1/scale)`. The DMGS
//! expansion is **parameterization-dependent**: the first-order truncation is not
//! invariant under nonlinear reparameterization, so computing it in `(shape,
//! rate)` (the core [`Gamma`] model) diverged from the reference by ~9% at
//! `n = 30` (confirmed by `tools/diag_gamma_cp.R`).
//!
//! Phase 5 fixes this by computing the expansion in the reference's
//! `(shape, scale)` parameterization via [`GammaScale`] (converting
//! `scale = 1/rate` at the boundary, exactly as the binding already does for the
//! density). The residual now matches the DMGS tolerance (`GAMMA_RTOL`). The
//! reference emits no CP quantiles for the gamma (it uses the numerical
//! `gamma_mu1f`/`gamma_mu2f`), so only the CP pdf is compared.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::dmgs::{dmgs_cp_pdf, dmgs_cp_quantiles};
use fitdistcp_core::mle::fit;
use fitdistcp_core::models::{Exponential, Gamma, GammaScale, Gumbel, LogNormal, Normal, Weibull};

/// Tolerance for the DMGS models (see module docs). As of W9 both the reference
/// and Rust use analytic derivatives, so the two agree to near machine
/// precision; the observed maximum relative residual is `1.2e-6` (weibull).
/// `1e-5` is a 100× tightening of the pre-W9 `1e-3` and still catches any
/// genuine formula/sign bug.
const DMGS_RTOL: f64 = 1e-5;
const DMGS_ATOL: f64 = 1e-10;

/// Tolerance for comparing the Rust DMGS output against the reference's
/// **exact analytic** CP for the analytic models. The DMGS expansion is a
/// first-order asymptotic approximation of the exact Bayesian integral, so at
/// `n = 30` the two differ by the `O(1/n)` truncation error (observed ~1%).
/// This is a documented, expected difference — the apples-to-apples DMGS
/// comparison above uses the full §7.2 tolerance.
const DMGS_TRUNC_RTOL: f64 = 5e-2;
const DMGS_TRUNC_ATOL: f64 = 1e-4;

/// Tolerance for the gamma CP pdf. Phase 5 (Issue 5) computes the DMGS expansion
/// in the reference's `(shape, scale)` parameterization (via [`GammaScale`]), so
/// the first-order truncation now matches the reference. The observed maximum
/// relative residual is `~1e-6` (the gamma density derivatives carry more
/// `powf` round-off than the closed-form models), so `GAMMA_RTOL = 1e-5` is a
/// 20000× tightening of the pre-Phase-5 `2e-1` and still catches any genuine
/// formula/sign bug.
const GAMMA_RTOL: f64 = 1e-5;
const GAMMA_ATOL: f64 = 1e-10;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
    /// Like [`Json::as_f64_vec`] but maps JSON `null` to `f64::NAN`.
    fn as_f64_vec_opt(&self) -> Vec<f64> {
        self.as_arr()
            .iter()
            .map(|v| match v {
                Json::Null => f64::NAN,
                Json::Num(n) => *n,
                other => panic!("expected number or null, got {other:?}"),
            })
            .collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.bytes[self.pos + 1..self.pos + 5])
                                .expect("utf8 hex");
                            let code = u32::from_str_radix(hex, 16).expect("hex");
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            self.pos += 4;
                        }
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "cp_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

#[test]
fn golden_cp_analytic_models() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let x_grid = root.get("x_grid").as_f64_vec();
    let p_grid = root.get("p_grid").as_f64_vec();

    let y_general = datasets.get("y_general").as_f64_vec();
    let y_positive = datasets.get("y_positive").as_f64_vec();

    // For the analytic models the reference exposes BOTH the exact analytic CP
    // (`cp_pdf`/`cp_quantiles`) and the DMGS-based CP (`dmgs_pdf`/
    // `dmgs_quantiles`). The Rust port implements the DMGS expansion, so the
    // apples-to-apples comparison is against the reference DMGS values, at the
    // full §7.2 tolerance. The exact analytic CP is also compared, with a
    // documented looser tolerance reflecting the O(1/n) DMGS truncation error
    // (the DMGS expansion is a first-order approximation of the exact integral).

    // --- norm (analytic + DMGS) ---------------------------------------------
    {
        let m = models.get("norm");
        let r = fit(&Normal, &y_general, &[10.0, 1.0]);
        let cp_pdf = dmgs_cp_pdf(Normal, &r.ml_params, &y_general, &x_grid);
        let cp_q = dmgs_cp_quantiles(Normal, &r.ml_params, &y_general, &p_grid);
        // Apples-to-apples: Rust DMGS vs reference DMGS. The reference uses
        // analytic density/CDF derivatives while Rust uses finite differences,
        // so the documented DMGS tolerance applies (confirmed by the FD-step
        // convergence diagnostic: at h=1e-6 the two agree to ~4e-8).
        compare_vec(
            &cp_pdf,
            &m.get("dmgs_pdf").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "norm.dmgs_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("dmgs_quantiles").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "norm.dmgs_q",
        );
        // Cross-check: Rust DMGS vs the exact analytic CP (looser, documented).
        compare_vec(
            &cp_pdf,
            &m.get("cp_pdf").as_f64_vec(),
            DMGS_TRUNC_RTOL,
            DMGS_TRUNC_ATOL,
            "norm.cp_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("cp_quantiles").as_f64_vec(),
            DMGS_TRUNC_RTOL,
            DMGS_TRUNC_ATOL,
            "norm.cp_q",
        );
    }

    // --- expon (analytic + DMGS) --------------------------------------------
    {
        let m = models.get("expon");
        let r = fit(&Exponential, &y_positive, &[1.0]);
        let cp_pdf = dmgs_cp_pdf(Exponential, &r.ml_params, &y_positive, &x_grid);
        let cp_q = dmgs_cp_quantiles(Exponential, &r.ml_params, &y_positive, &p_grid);
        compare_vec(
            &cp_pdf,
            &m.get("dmgs_pdf").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "expon.dmgs_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("dmgs_quantiles").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "expon.dmgs_q",
        );
        compare_vec(
            &cp_pdf,
            &m.get("cp_pdf").as_f64_vec(),
            DMGS_TRUNC_RTOL,
            DMGS_TRUNC_ATOL,
            "expon.cp_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("cp_quantiles").as_f64_vec(),
            DMGS_TRUNC_RTOL,
            DMGS_TRUNC_ATOL,
            "expon.cp_q",
        );
    }

    // --- lnorm (analytic + DMGS) --------------------------------------------
    {
        let m = models.get("lnorm");
        let r = fit(&LogNormal, &y_positive, &[0.0, 1.0]);
        let cp_pdf = dmgs_cp_pdf(LogNormal, &r.ml_params, &y_positive, &x_grid);
        let cp_q = dmgs_cp_quantiles(LogNormal, &r.ml_params, &y_positive, &p_grid);
        compare_vec(
            &cp_pdf,
            &m.get("dmgs_pdf").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "lnorm.dmgs_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("dmgs_quantiles").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "lnorm.dmgs_q",
        );
        compare_vec(
            &cp_pdf,
            &m.get("cp_pdf").as_f64_vec(),
            DMGS_TRUNC_RTOL,
            DMGS_TRUNC_ATOL,
            "lnorm.cp_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("cp_quantiles").as_f64_vec(),
            DMGS_TRUNC_RTOL,
            DMGS_TRUNC_ATOL,
            "lnorm.cp_q",
        );
    }
}

/// Phase 5 (Issue 5): measure and pin the gamma and Weibull CP-pdf residuals.
///
/// The gamma residual is the headline Phase 5 improvement: computing the DMGS
/// expansion in the reference `(shape, scale)` parameterization drops it from
/// ~9% (the pre-Phase-5 `(shape, rate)` divergence) to the DMGS tolerance. The
/// Weibull residual is the `powf`-round-off reduction from the `ln_1p`/`exp_m1`
/// rewrite.
#[test]
fn golden_gamma_weibull_residuals() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let x_grid = root.get("x_grid").as_f64_vec();
    let y_positive = datasets.get("y_positive").as_f64_vec();

    // --- gamma: (shape, scale) DMGS expansion -------------------------------
    {
        let m = models.get("gamma");
        let ref_params = m.get("params").as_f64_vec(); // [shape, scale]
        let r = fit(&Gamma, &y_positive, &[1.0, 1.0]);
        let scale_params = [r.ml_params[0], 1.0 / r.ml_params[1]];
        let cp_pdf = dmgs_cp_pdf(GammaScale, &scale_params, &y_positive, &x_grid);
        let expected = m.get("cp_pdf").as_f64_vec();
        let max_rel = cp_pdf
            .iter()
            .zip(expected.iter())
            .map(|(a, e)| (a - e).abs() / e.abs().max(1e-300))
            .fold(0.0_f64, f64::max);
        // The pre-Phase-5 (shape, rate) divergence was ~9% at n = 30; the
        // (shape, scale) expansion drops it to ~2.2e-7.
        assert!(
            max_rel < GAMMA_RTOL,
            "gamma CP pdf max relative residual {max_rel:.3e} exceeds GAMMA_RTOL {GAMMA_RTOL:.1e}"
        );
        // Sanity: the reference params are the (shape, scale) MLE.
        assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "gamma.shape");
        assert_close(
            1.0 / r.ml_params[1],
            ref_params[1],
            1e-4,
            1e-6,
            "gamma.scale",
        );
    }

    // --- weibull: powf round-off reduction ----------------------------------
    {
        let m = models.get("weibull");
        let r = fit(&Weibull, &y_positive, &[1.0, 1.0]);
        let cp_pdf = dmgs_cp_pdf(Weibull, &r.ml_params, &y_positive, &x_grid);
        let expected = m.get("cp_pdf").as_f64_vec();
        let max_rel = cp_pdf
            .iter()
            .zip(expected.iter())
            .map(|(a, e)| (a - e).abs() / e.abs().max(1e-300))
            .fold(0.0_f64, f64::max);
        // The pre-Phase-5 Weibull residual was 1.2e-6; the ln_1p/exp_m1 rewrite
        // keeps it below that (observed ~1.18e-6, dominated by the absolute
        // round-off of the DMGS correction in the tail where the density is
        // tiny — not a formula error).
        assert!(
            max_rel < 1.2e-6,
            "weibull CP pdf max relative residual {max_rel:.3e} not below the pre-Phase-5 1.2e-6"
        );
    }
}

#[test]
fn golden_cp_dmgs_models() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let x_grid = root.get("x_grid").as_f64_vec();
    let p_grid = root.get("p_grid").as_f64_vec();

    let y_general = datasets.get("y_general").as_f64_vec();
    let y_positive = datasets.get("y_positive").as_f64_vec();

    // --- gumbel (DMGS) ------------------------------------------------------
    {
        let m = models.get("gumbel");
        let r = fit(&Gumbel, &y_general, &[10.0, 2.0]);
        let cp_pdf = dmgs_cp_pdf(Gumbel, &r.ml_params, &y_general, &x_grid);
        let cp_q = dmgs_cp_quantiles(Gumbel, &r.ml_params, &y_general, &p_grid);
        compare_vec(
            &cp_pdf,
            &m.get("cp_pdf").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "gumbel.cp_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("cp_quantiles").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "gumbel.cp_q",
        );
    }

    // --- weibull (DMGS) -----------------------------------------------------
    {
        let m = models.get("weibull");
        let r = fit(&Weibull, &y_positive, &[1.0, 1.0]);
        let cp_pdf = dmgs_cp_pdf(Weibull, &r.ml_params, &y_positive, &x_grid);
        let cp_q = dmgs_cp_quantiles(Weibull, &r.ml_params, &y_positive, &p_grid);
        compare_vec(
            &cp_pdf,
            &m.get("cp_pdf").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "weibull.cp_pdf",
        );
        compare_vec(
            &cp_q,
            &m.get("cp_quantiles").as_f64_vec(),
            DMGS_RTOL,
            DMGS_ATOL,
            "weibull.cp_q",
        );
    }

    // --- gamma (DMGS; reference (shape, scale) parameterization) ------------
    {
        let m = models.get("gamma");
        let ref_params = m.get("params").as_f64_vec(); // [shape, scale]
        let rate = 1.0 / ref_params[1];
        // Fit in the Rust (shape, rate) parameterization.
        let r = fit(&Gamma, &y_positive, &[1.0, 1.0]);
        // The Rust MLE rate should match the reference scale converted to rate.
        assert_close(r.ml_params[0], ref_params[0], 1e-4, 1e-6, "gamma.shape");
        assert_close(r.ml_params[1], rate, 1e-4, 1e-6, "gamma.rate");
        // Phase 5 (Issue 5): compute the DMGS expansion in the reference's
        // (shape, scale) parameterization (convert scale = 1/rate at the
        // boundary). This is the fix for the ~9% divergence: the first-order
        // DMGS truncation is not invariant under nonlinear reparameterization,
        // so it must be evaluated in the reference's parameterization.
        let scale_params = [r.ml_params[0], 1.0 / r.ml_params[1]];
        let cp_pdf = dmgs_cp_pdf(GammaScale, &scale_params, &y_positive, &x_grid);
        compare_vec(
            &cp_pdf,
            &m.get("cp_pdf").as_f64_vec(),
            GAMMA_RTOL,
            GAMMA_ATOL,
            "gamma.cp_pdf",
        );
        // The reference emits no CP quantiles for the gamma (see module docs);
        // assert the fixture is null so a future change is noticed.
        let ref_q = m.get("cp_quantiles").as_f64_vec_opt();
        assert!(
            ref_q.iter().all(|v| v.is_nan()),
            "gamma.cp_quantiles fixture unexpectedly non-null"
        );
    }
}
